package com.aicharacter.v3;
/** Shared active/offline ordering. Fine steps are reserved for motion/falls; quiet grounded biology advances efficiently without discarding time. */
public final class BiomechanicsStepEngine{private BiomechanicsStepEngine(){}
 public static void advance(WorldState s,double seconds,long now){if(s==null||seconds<=0)return;double remain=seconds,elapsed=0;long start=Math.max(0L,now-(long)(seconds*1000.0));int guard=0;while(remain>1e-6&&guard++<200000){boolean dynamic=(s.girlPhysics!=null&&(s.girlPhysics.falling||!s.girlPhysics.grounded))||(s.catPhysics!=null&&(s.catPhysics.falling||!s.catPhysics.grounded))||(s.girlTravel!=null&&s.girlTravel.active)||(s.catTravel!=null&&s.catTravel.active);double dt=Math.min(remain,dynamic?.25:Math.min(15.0,remain));long subNow=Math.min(now,start+(long)((elapsed+dt)*1000.0));DigestionHydrationEngine.advance(s,dt,subNow);CardioMetabolicEngine.advance(s,dt);RecoveryEngine.advance(s,dt,subNow);PainLocalizationEngine.advance(s,dt,subNow);MusculoskeletalEngine.advance(s,dt);CatCardioMetabolicEngine.advance(s,dt,subNow);NervousSystemEngine.advance(s,dt,subNow);WholeBodyMotorEngine.advance(s,dt);JointConstraintEngine.solve(s);NervousSystemEngine.observePostMotorSupport(s,dt,subNow);CatNervousSystemEngine.advance(s,dt,subNow);CatWholeBodyMotorEngine.advance(s,dt);CatNervousSystemEngine.observePostMotorSupport(s,dt,subNow);WholeBodyPhysicsEngine.prepare(s,"girl",dt,subNow);WholeBodyPhysicsEngine.prepare(s,"cat",dt,subNow);remain-=dt;elapsed+=dt;}if(remain>1e-6){double dt=remain;DigestionHydrationEngine.advance(s,dt,now);SystemicHomeostasisEngine.advance(s,dt,now);CardioMetabolicEngine.advance(s,dt);RecoveryEngine.advance(s,dt,now);PainLocalizationEngine.advance(s,dt,now);MusculoskeletalEngine.advance(s,dt);CatCardioMetabolicEngine.advance(s,dt,now);NervousSystemEngine.advance(s,dt,now);WholeBodyMotorEngine.advance(s,dt);JointConstraintEngine.solve(s);NervousSystemEngine.observePostMotorSupport(s,dt,now);CatNervousSystemEngine.advance(s,dt,now);CatWholeBodyMotorEngine.advance(s,dt);CatNervousSystemEngine.observePostMotorSupport(s,dt,now);WholeBodyPhysicsEngine.prepare(s,"girl",dt,now);WholeBodyPhysicsEngine.prepare(s,"cat",dt,now);}}
}